// Test Suite for U28_misc, VCMCL03-1, VCMCL03-2, VCMSYM01, VCMSYM02, VCMPA01, VCDPA02

// Test for Edit/Update Chemist/Labs Screen
[Test]
public void EditUpdateChemistLabScreen_ShouldDisplayAndModifyDetails() {
    // Arrange
    ChemistLab chemistLab = new ChemistLab("123", "Lab A", "123 Main St", "John Doe", "555-1234");
    // Act
    chemistLab.editLabDetails("123", "Lab B", "123 Main St", "Jane Doe", "555-4321");
    // Assert
    assertEquals("Lab B", chemistLab.getLabName());
    assertEquals("123 Main St", chemistLab.getAddress());
    assertEquals("Jane Doe", chemistLab.getContactDetails());
}

[Test]
public void EditUpdateChemistLabScreen_ShouldDisplayAndDeleteDetails() {
    // Arrange
    ChemistLab chemistLab = new ChemistLab("123", "Lab A", "123 Main St", "John Doe", "555-1234");
    // Act
    chemistLab.deleteLabDetails();
    // Assert
    assertNull(chemistLab.getLabDetails());
}

[Test]
public void EditUpdateChemistLabScreen_ShouldDisplayErrorWhenLabDoesNotExist() {
    // Arrange
    ChemistLab chemistLab = new ChemistLab("999", "Lab X", "999 Main St", "John Doe", "555-1234");
    // Act
    assertThrows(new ChemistLabNotFoundException("Chemist or Lab does not exist"));
    // Assert
    assertNull(chemistLab.getLabDetails());
}

// Test for Deleting Chemist or Lab Details
[Test]
public void DeleteChemistLabDetails_ShouldCheckPrescriptionsBeforeDeletion() {
    // Arrange
    ChemistLab chemistLab = new ChemistLab("123", "Lab A", "123 Main St", "John Doe", "555-1234");
    // Act
    chemistLab.deleteLabDetails();
    // Assert
    assertThrows(new PrescriptionRequestException("Chemist or Lab has open Prescription Requests - cannot delete"));
}

// Test for Administrators Menu Screen to Maintain Symptoms
[Test]
public void AdminMenuSymptomScreen_ShouldAddSymptomCode() {
    // Arrange
    AdminMenu adminMenu = new AdminMenu();
    // Act
    adminMenu.addSymptomCode("C001", "Cough");
    // Assert
    assertEquals("C001", adminMenu.getSymptomCode("Cough"));
}

[Test]
public void AdminMenuSymptomScreen_ShouldEditUpdateSymptomCode() {
    // Arrange
    AdminMenu adminMenu = new AdminMenu();
    // Act
    adminMenu.editSymptomCode("C001", "Cough", "Sneezing");
    // Assert
    assertEquals("Sneezing", adminMenu.getSymptomCode("Cough"));
}

// Test for Add Symptom Code Screen
[Test]
public void AddSymptomCodeScreen_ShouldDisplaySymptomCodeAndDescription() {
    // Arrange
    SymptomCode symptomCode = new SymptomCode("C001", "Cough");
    // Act
    assertEquals("C001", symptomCode.getSymptomCode());
    assertEquals("Cough", symptomCode.getSymptomDescription());
}

// Test for Edit/Update Symptom Screen
[Test]
public void EditUpdateSymptomScreen_ShouldDisplaySymptomCodeAndDescription() {
    // Arrange
    SymptomCode symptomCode = new SymptomCode("C001", "Cough");
    // Act
    symptomCode.editSymptomCode("C001", "Sneezing");
    // Assert
    assertEquals("Sneezing", symptomCode.getSymptomCode());
    assertEquals("Sneezing", symptomCode.getSymptomDescription());
}

// Test for Update Patient Profile
[Test]
public void UpdatePatientProfile_ShouldGeneratePrescriptionReport() {
    // Arrange
    Patient patient = new Patient("John Doe", "123 Main St", "555-1234");
    // Act
    patient.generatePrescriptionReport();
    // Assert
    assertNotNull(patient.getPrescriptionReport());
}

// Test for Patient Id Screen
[Test]
public void PatientIdScreen_ShouldCapturePatientDetails() {
    // Arrange
    Patient patient = new Patient("John Doe", "123 Main St", "555-1234");
    // Act
    assertEquals("John Doe", patient.getName());
    assertEquals("123 Main St", patient.getAddress());
    assertEquals("555-1234", patient.getContactDetails());
}
